      lines.push(`### ${side}: ${c.scope.routeId} · ${c.route.method}${c.route.path?' '+c.route.path:''}`,'',
        `Saved mapping: ${c.scope.inputs.resource}; ${c.caseMatches?'matches current case':'earlier mapping'}`,
