        need(existing.configSha256 === request.configSha256 &&
          existing.sourceConfigSha256 === sourceConfigSha256 && existing.bodySha256 === bodySha256 &&
          (existing.operationTicket?.sha256 ?? null) === (ticket?.sha256 ?? null) &&
