      if (!HASH.test(entry.name)) continue;
      need(entry.isDirectory() && !entry.isSymbolicLink(), 'INBOX_JOB_DIRECTORY_INVALID');
      let intentId;
      try {
        const r = (await jsonFile(join(root, 'jobs', entry.name, 'request.json'))).value;
        intentId = r.operation?.intentId;
